alter table surveys add column if not exists max_responses int check(max_responses>0);

create or replace function get_public_survey(p_slug text) returns jsonb language sql security definer set search_path=public,pg_temp as $$select jsonb_build_object('survey',jsonb_build_object('slug',s.public_slug,'title',s.title,'description',s.description,'targetType',s.target_type,'responseMode',s.response_mode,'identityFields',s.identity_fields,'privacyNotice',s.privacy_notice,'duplicatePolicy',s.duplicate_policy,'status',case when s.status='open' and s.starts_at is not null and now()<s.starts_at then 'scheduled' when s.status='open' and s.ends_at is not null and now()>s.ends_at then 'closed' when s.status='open' and s.max_responses is not null and (select count(*) from survey_responses r where r.survey_id=s.id)>=s.max_responses then 'closed' else s.status end,'startsAt',s.starts_at,'endsAt',s.ends_at,'maxResponses',s.max_responses,'responseCount',(select count(*) from survey_responses r where r.survey_id=s.id),'completionMessage',s.completion_message),'questions',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'type',q.type,'title',q.title,'description',q.description,'isRequired',q.is_required,'minSelections',q.min_selections,'maxSelections',q.max_selections,'scaleMinLabel',q.scale_min_label,'scaleMaxLabel',q.scale_max_label,'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'isOther',o.is_other) order by o.display_order) from survey_options o where o.question_id=q.id),'[]'::jsonb)) order by q.display_order) from survey_questions q where q.survey_id=s.id),'[]'::jsonb)) from surveys s where s.public_slug=p_slug and s.status not in ('draft','archived')$$;

create or replace function submit_public_survey(p_slug text,p_token text,p_respondent_fields jsonb,p_answers jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare s surveys%rowtype;r_id uuid;q survey_questions%rowtype;a jsonb;a_id uuid;ids uuid[];oid uuid;begin select * into s from surveys where public_slug=p_slug for update;if not found then raise exception 'survey_not_found';end if;if s.status<>'open' or (s.starts_at is not null and now()<s.starts_at) or (s.ends_at is not null and now()>s.ends_at) then raise exception 'survey_not_open';end if;if s.max_responses is not null and (select count(*) from survey_responses where survey_id=s.id)>=s.max_responses then raise exception 'survey_full';end if;if octet_length(coalesce(p_answers::text,''))>100000 then raise exception 'payload_too_large';end if;if s.duplicate_policy='browser_once' and exists(select 1 from survey_responses where survey_id=s.id and browser_submission_token=p_token) then raise exception 'duplicate_submission';end if;if (select count(*) from survey_responses where survey_id=s.id and browser_submission_token=p_token and submitted_at>now()-interval '1 minute')>=5 then raise exception 'rate_limited';end if;if s.response_mode='anonymous' then p_respondent_fields='{}'::jsonb;end if;for q in select * from survey_questions where survey_id=s.id order by display_order loop a=(select x from jsonb_array_elements(p_answers)x where x->>'questionId'=q.id::text limit 1);if q.is_required and (a is null or (q.type in ('short','long') and btrim(coalesce(a->>'textValue',''))='') or (q.type in ('single','multiple') and jsonb_array_length(coalesce(a->'optionIds','[]'))=0) or (q.type='scale5' and a->>'scaleValue' is null)) then raise exception 'required_answer_missing';end if;if a is null then continue;end if;if q.type in ('single','multiple') then select array_agg(value::uuid) into ids from jsonb_array_elements_text(coalesce(a->'optionIds','[]'));if q.type='single' and coalesce(array_length(ids,1),0)>1 then raise exception 'single_choice_invalid';end if;if q.type='multiple' and ((q.min_selections is not null and coalesce(array_length(ids,1),0)<q.min_selections) or (q.max_selections is not null and coalesce(array_length(ids,1),0)>q.max_selections)) then raise exception 'selection_count_invalid';end if;if exists(select 1 from unnest(coalesce(ids,array[]::uuid[])) x where not exists(select 1 from survey_options o where o.id=x and o.question_id=q.id)) then raise exception 'option_relation_invalid';end if;end if;if q.type='scale5' and ((a->>'scaleValue')::int not between 1 and 5) then raise exception 'scale_invalid';end if;end loop;insert into survey_responses(survey_id,respondent_fields,browser_submission_token) values(s.id,coalesce(p_respondent_fields,'{}'),p_token) returning id into r_id;for a in select * from jsonb_array_elements(p_answers) loop select * into q from survey_questions where id=(a->>'questionId')::uuid and survey_id=s.id;if not found then raise exception 'question_relation_invalid';end if;insert into survey_answers(response_id,question_id,option_id,text_value,scale_value) values(r_id,q.id,case when q.type='single' and jsonb_array_length(coalesce(a->'optionIds','[]'))=1 then (a->'optionIds'->>0)::uuid else null end,nullif(btrim(coalesce(a->>'textValue','')),''),case when q.type='scale5' then (a->>'scaleValue')::int else null end) returning id into a_id;if q.type='multiple' then for oid in select value::uuid from jsonb_array_elements_text(coalesce(a->'optionIds','[]')) loop insert into survey_answer_options(answer_id,option_id) values(a_id,oid);end loop;end if;end loop;return jsonb_build_object('ok',true,'completionMessage',s.completion_message);end$$;
